#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "film_scene_render_binding_candidate.h"
#include "film_shot_time_candidate.h"
#include "session_color_timeline_subset.h"
#include "session_model_placement_candidate.h"
#include "session_camera_view_projection_candidate.h"
#include "session_bone_pose_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=5&&argc!=6&&argc!=7)throw std::runtime_error("session film-clip-or-root-id content-root fresh-output-directory [root-parent-tick [--sample-subset]] required");size_t used=0;std::string idText=argv[2];auto clip=std::stoul(idText,&used);if(used!=idText.size()||clip>UINT32_MAX)throw std::runtime_error("clip id");auto graph=loadGraph(argv[1]);int32_t selectedLocalTick=0,selectedParentTick=0;size_t sampledExecuted=0,sampledChanged=0;bool sampled=argc==7;if(sampled&&std::string(argv[6])!="--sample-subset")throw std::runtime_error("unsupported export option");if(argc>=6){size_t tickUsed=0;std::string tickText=argv[5];auto tick=std::stoll(tickText,&tickUsed);if(tickUsed!=tickText.size()||tick<INT32_MIN||tick>INT32_MAX)throw std::runtime_error("timeline tick");auto selected=selectFilmShotCandidate(graph,uint32_t(clip),int32_t(tick));clip=selected.clip;selectedLocalTick=selected.localTick;selectedParentTick=selected.parentTick;}if(sampled){auto evaluated=evaluateSessionColorTimelineSubsetCandidate(std::move(graph),selectedParentTick,uint32_t(clip));sampledExecuted=evaluated.executed;sampledChanged=evaluated.changed;graph=std::move(evaluated.graph);}auto binding=readFilmSceneRenderBindingCandidate(graph,uint32_t(clip));auto root=std::filesystem::weakly_canonical(argv[3]);auto directory=std::filesystem::path(argv[4]);if(std::filesystem::exists(directory))throw std::runtime_error("refuse output directory overwrite");auto camera=sessionCameraViewProjectionCandidate(graph,binding.camera,512,512,true);GraphTransformHierarchy hierarchy(graph);
 struct Model{uint32_t id;SessionModelPlacementCandidate placement;std::vector<GeometryMatrixCandidate>locals;};std::vector<Model>models;
 for(auto id:binding.models){auto placement=readSessionModelPlacementCandidate(graph,id,hierarchy);auto name=placement.asset;for(char&c:name)if(c=='\\')c='/';std::filesystem::path relative(name);if(relative.is_absolute()||relative.has_root_name()||relative.has_root_directory()||name.find(':')!=std::string::npos)throw std::runtime_error("model asset path");for(auto&part:relative)if(part=="..")throw std::runtime_error("model traversal");auto asset=std::filesystem::weakly_canonical(root/relative);auto inside=asset.lexically_relative(root);if(inside.empty()||*inside.begin()=="..")throw std::runtime_error("asset outside mount");std::ifstream file(asset,std::ios::binary);if(!file)throw std::runtime_error("shot model asset missing: "+name);std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});auto bones=readGeometrySkeletonCandidate(bytes);auto locals=readSessionBonePoseCandidate(graph,id,bones);evaluateGeometryPosePaletteCandidate(bones,locals);models.push_back({id,std::move(placement),std::move(locals)});}
 std::filesystem::create_directories(directory);auto write=[&](const std::filesystem::path&path,const void*data,size_t bytes){std::ofstream file(directory/path,std::ios::binary);file.write(static_cast<const char*>(data),std::streamsize(bytes));file.close();if(!file)throw std::runtime_error("shot input write");};write("camera.bin",&camera,64);std::ofstream manifest(directory/"manifest.txt");manifest<<"clip="<<binding.clip<<" camera="<<binding.camera<<" scene="<<binding.scene<<" viewport=512x512 engine_axes=1\n";
 if(argc>=6)manifest<<"root_parent_tick="<<argv[5]<<" selected_local_tick="<<selectedLocalTick<<" selection_policy=candidate_half_open animation_sampled="<<(sampled?"recovered_subset":"no")<<" sampled_executed="<<sampledExecuted<<" sampled_changed="<<sampledChanged<<" native_scheduler=unfinished\n";
 for(size_t n=0;n<models.size();++n){auto&model=models[n];auto prefix="model-"+std::to_string(n);write(prefix+"-placement.bin",&model.placement.matrix,64);uint32_t count=uint32_t(model.locals.size());std::vector<uint8_t>pose(4+model.locals.size()*48);std::memcpy(pose.data(),&count,4);std::memcpy(pose.data()+4,model.locals.data(),model.locals.size()*48);write(prefix+"-pose.bin",pose.data(),pose.size());manifest<<prefix<<" element="<<model.id<<" asset="<<model.placement.asset<<" bones="<<count<<'\n';}manifest.close();if(!manifest)throw std::runtime_error("shot manifest write");std::cout<<"shot render export passed clip="<<binding.clip<<" camera="<<binding.camera<<" models="<<models.size()<<" native_full_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
